INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207EOMZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $16$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$8\\pi$"},{"key":"B","text":"$16\\pi$"},{"key":"C","text":"$64\\pi$"},{"key":"D","text":"$256\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. With $d = 16$: $C = 16\\pi$ centimeters. The value $8\\pi$ comes from using the radius ($r = 8$) in the formula $\\pi r$ instead of $2\\pi r$ or $\\pi d$, effectively halving the result. The value $64\\pi$ results from using the area formula for the radius, computing $\\pi r^2 = \\pi(8)^2 = 64\\pi$. The value $256\\pi$ comes from using the diameter in the area formula: $\\pi(16)^2 = 256\\pi$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20XCF7F', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = -3(x + 1)^2 + 12$ is defined for all real numbers. What is the maximum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$3$"},{"key":"C","text":"$12$"},{"key":"D","text":"$-12$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $a(x - h)^2 + k$ with $a = -3$, $h = -1$, and $k = 12$. Since $a < 0$, the parabola opens downward and the vertex represents the maximum point. The maximum value of the function is $k = 12$. The value $-1$ is the $x$-coordinate where the maximum occurs, not the maximum output itself. The value $3$ confuses the absolute value of the leading coefficient with the maximum. The value $-12$ applies an incorrect sign to the constant term $12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22SM5R9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scatterplot shows the relationship between the number of employees $e$ at a company and the company''s annual revenue $r$ (in millions of dollars). The line of best fit is $r = 0.4e + 2.8$. A company with $35$ employees has an actual annual revenue of $\\$18$ million. What is the residual for this company, in millions of dollars?', NULL, $lyceon_json$[{"key":"A","text":"$-1.2$"},{"key":"B","text":"$1.2$"},{"key":"C","text":"$1.8$"},{"key":"D","text":"$16.8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted revenue is $r = 0.4(35) + 2.8 = 14 + 2.8 = 16.8$ million. The residual is the actual value minus the predicted value: $18 - 16.8 = 1.2$ million. The result $-1.2$ reverses the subtraction order, computing predicted minus actual instead of actual minus predicted. The result $1.8$ comes from an arithmetic slip such as computing $18 - 16.2$. The result $16.8$ is the predicted value itself, not the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM236UW5D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A fitness magazine reported that people who eat breakfast every day weigh less on average than people who skip breakfast. The data came from a survey in which participants reported their own eating habits. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast every day causes weight loss."},{"key":"B","text":"Skipping breakfast causes weight gain."},{"key":"C","text":"There is an association between eating breakfast daily and lower weight, but the survey cannot establish that one causes the other."},{"key":"D","text":"The survey proves that breakfast has no effect on weight because it was not a controlled experiment."}]$lyceon_json$::jsonb, 'C', NULL, E'Because participants self-selected their breakfast habits, this is an observational study. People who eat breakfast daily may differ in other ways, such as overall diet quality or exercise habits, that also influence weight. The survey can identify an association but cannot establish causation without random assignment. The claim that eating breakfast causes weight loss assumes a causal relationship that the study design cannot support. Similarly, claiming that skipping breakfast causes weight gain reverses the framing but makes the same unsupported causal leap. The claim that the survey proves no effect overstates the limitation; the inability to establish causation does not mean the treatment has no effect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23F84AS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set of $20$ values has a mean of $65$. The $5$ largest values are removed, and the mean of the remaining $15$ values is $58$. What is the mean of the $5$ removed values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '86', ARRAY['86'], E'The sum of all $20$ values is $20 \\times 65 = 1{,}300$. The sum of the remaining $15$ values is $15 \\times 58 = 870$. The sum of the $5$ removed values is $1{,}300 - 870 = 430$. Therefore the mean of the $5$ removed values is $\\frac{430}{5} = 86$. A common error is subtracting the means directly ($65 - 58 = 7$) instead of working with the sums, which ignores the different group sizes. Another error is dividing the total sum by $5$ without subtracting the remaining group''s sum, yielding $\\frac{1{,}300}{5} = 260$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2468A14', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A candle is $30$ centimeters tall when it is first lit. It burns at a constant rate and is $18$ centimeters tall after $4$ hours. Which function $h(t)$ gives the height, in centimeters, of the candle after $t$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$h(t) = 30 - 3t$"},{"key":"B","text":"$h(t) = 30 - 4.5t$"},{"key":"C","text":"$h(t) = 18 - 3t$"},{"key":"D","text":"$h(t) = 30 + 3t$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $h(t) = 30 - 3t$. The candle starts at $30$ cm and is $18$ cm after $4$ hours, so it lost $30 - 18 = 12$ cm in $4$ hours, giving a burn rate of $\\frac{12}{4} = 3$ cm per hour. Since the candle decreases in height, the function is $h(t) = 30 - 3t$. The expression $30 - 4.5t$ uses an incorrect rate obtained by dividing $18$ by $4$ instead of computing the change in height per hour. The expression $18 - 3t$ uses the height at $4$ hours as the initial value instead of the starting height. The expression $30 + 3t$ incorrectly adds the rate, implying the candle grows taller.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24C4S9F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'At a summer camp, $180$ campers were asked whether they preferred swimming or hiking. Of the $110$ campers aged $10$–$13$, $70$ preferred swimming. Of the $70$ campers aged $14$–$17$, $25$ preferred swimming. If a camper who preferred hiking is selected at random, what is the probability that the camper is aged $14$–$17$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{17}$"},{"key":"B","text":"$\\frac{45}{180}$"},{"key":"C","text":"$\\frac{45}{70}$"},{"key":"D","text":"$\\frac{40}{70}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Campers who preferred hiking: from the younger group, $110 - 70 = 40$ preferred hiking; from the older group, $70 - 25 = 45$ preferred hiking. The total number of hikers is $40 + 45 = 85$. Given that a camper preferred hiking, the probability the camper is aged $14$–$17$ is $\\frac{45}{85} = \\frac{9}{17}$. The distractor $\\frac{45}{180}$ divides $45$ by the total number of campers rather than conditioning on the hiking preference. The distractor $\\frac{45}{70}$ divides the number of older hikers by the total number of older campers, which conditions on age rather than on preference. The distractor $\\frac{40}{70}$ confuses the younger hikers count with an unrelated ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM253MMYO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A school club needs to raise more than $\\$200$ for a field trip. The club has already raised $\\$135$ through a bake sale. If each car wash ticket sells for $\\$5$, which inequality represents the number of tickets $t$ the club must sell to reach its goal?', NULL, $lyceon_json$[{"key":"A","text":"$t > 13$"},{"key":"B","text":"$t \\geq 13$"},{"key":"C","text":"$t > 40$"},{"key":"D","text":"$t < 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The club needs the total to exceed $\\$200$, so $135 + 5t > 200$, which simplifies to $5t > 65$, giving $t > 13$. The distractor $t \\geq 13$ uses a non-strict inequality, but the problem says "more than" $\\$200$, so exactly $\\$200$ does not meet the goal and $t = 13$ (which yields exactly $\\$200$) must be excluded. The distractor $t > 40$ divides $\\$200$ by $\\$5$ without accounting for the $\\$135$ already raised. The distractor $t < 13$ reverses the direction of the inequality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26TCNQ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A bag contains $5$ red chips, $4$ white chips, and $3$ blue chips. Two chips are drawn at random without replacement. Given that the first chip drawn is red, what is the probability that the second chip drawn is also red?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{12}$"},{"key":"B","text":"$\\frac{25}{144}$"},{"key":"C","text":"$\\frac{4}{11}$"},{"key":"D","text":"$\\frac{1}{4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'There are $5 + 4 + 3 = 12$ chips total. Given that the first chip drawn is red, there are now $4$ red chips remaining out of $11$ chips total. The probability that the second chip is also red is $\\frac{4}{11}$. The distractor $\\frac{5}{12}$ gives the probability of drawing a red chip on the first draw, ignoring the condition entirely and not accounting for the removal of a chip. The distractor $\\frac{25}{144}$ multiplies $\\frac{5}{12} \\times \\frac{5}{12}$, treating the draws as independent with replacement and computing the joint probability rather than the conditional probability. The distractor $\\frac{1}{4}$ likely results from an arithmetic error such as computing $\\frac{4}{16}$ or $\\frac{3}{12}$ and simplifying incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26TG7FL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following ordered pairs $(x, y)$ satisfies both $2x - y < 6$ and $x + 3y \\geq 9$?', NULL, $lyceon_json$[{"key":"A","text":"$(5, 2)$"},{"key":"B","text":"$(4, 1)$"},{"key":"C","text":"$(0, 3)$"},{"key":"D","text":"$(3, 0)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Testing $(0, 3)$: the first inequality gives $2(0) - 3 = -3 < 6$, which is true, and the second gives $0 + 3(3) = 9 \\geq 9$, which is also true. Both inequalities are satisfied. For $(5, 2)$: $2(5) - 2 = 8$, which is not less than $6$, so the first inequality fails. For $(4, 1)$: $2(4) - 1 = 7$, which is not less than $6$, so the first inequality fails. For $(3, 0)$: the first inequality gives $2(3) - 0 = 6$, which is not strictly less than $6$, so it fails.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27JHT3U', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $8$ and the hypotenuse has length $17$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$15$"},{"key":"C","text":"$19$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem: $a^2 + 8^2 = 17^2$, so $a^2 = 289 - 64 = 225$ and $a = 15$. The value $9$ comes from subtracting the lengths directly ($17 - 8 = 9$) instead of using the Pythagorean theorem. The value $19$ results from adding the squares incorrectly as $a^2 = 64 + 289 = 353$ and approximating, treating both given lengths as legs. The value $25$ comes from an arithmetic slip such as computing $289 + 64 = 353$ and misidentifying a square root.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2885F4O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 3x + 12$. What is the predicted value of $y$ when $x = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$17$"},{"key":"C","text":"$27$"},{"key":"D","text":"$60$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 5$ gives $y = 3(5) + 12 = 15 + 12 = 27$. The result $15$ comes from computing $3 \\times 5$ but forgetting to add the $y$-intercept. The result $17$ arises from an arithmetic slip such as adding $5 + 12$ instead of $15 + 12$. The result $60$ comes from multiplying $12 \\times 5$ instead of substituting into the equation correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29453GT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A technology company emailed a job satisfaction survey to $4{,}000$ randomly selected employees. Only $600$ employees responded, and $85\\%$ of respondents reported being "satisfied" or "very satisfied" with their jobs. The company''s CEO announced that $85\\%$ of all employees are satisfied. Which of the following best explains why this conclusion may be invalid?', NULL, $lyceon_json$[{"key":"A","text":"The sample of $4{,}000$ employees was not randomly selected from the company's workforce."},{"key":"B","text":"Employees who are more satisfied may have been more likely to respond, so the $85\\%$ figure may overestimate satisfaction among all employees."},{"key":"C","text":"The survey should have included former employees to provide a complete picture of satisfaction."},{"key":"D","text":"A margin of error was not reported, so the $85\\%$ figure is meaningless."}]$lyceon_json$::jsonb, 'B', NULL, E'The response rate was only $\\frac{600}{4{,}000} = 15\\%$. This low response rate introduces nonresponse bias: employees who are satisfied may be more willing to complete a satisfaction survey, while dissatisfied employees may ignore it or fear repercussions. This systematic difference between respondents and non-respondents can inflate the reported satisfaction rate. The distractor about random selection contradicts the problem statement, which specifies the sample was randomly selected. The distractor about including former employees is irrelevant because the claim concerns current employees. The distractor about a missing margin of error identifies a secondary issue, but even with a margin of error, the estimate would remain biased due to the differential nonresponse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM299MIXI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cone has a radius of $6$ centimeters and a height of $8$ centimeters. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$96\\pi$"},{"key":"B","text":"$288\\pi$"},{"key":"C","text":"$48\\pi$"},{"key":"D","text":"$192\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(6)^2(8) = \\frac{1}{3}\\pi(36)(8) = \\frac{288\\pi}{3} = 96\\pi$ cubic centimeters. The value $288\\pi$ comes from omitting the $\\frac{1}{3}$ factor, computing $\\pi r^2 h = 288\\pi$ as if it were a cylinder. The value $48\\pi$ results from an arithmetic slip such as computing $\\frac{1}{3}(36)(8) = \\frac{1}{3}(144) = 48$ instead of $\\frac{1}{3}(288) = 96$. The value $192\\pi$ comes from applying the $\\frac{1}{3}$ factor to only part of the expression, such as computing $\\frac{1}{3}(8) \\times 36 \\times 2 = 192$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B1HW2F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A student answered $36$ out of $45$ questions correctly on a test. What percent of the questions did the student answer correctly?', NULL, $lyceon_json$[{"key":"A","text":"$72\\%$"},{"key":"B","text":"$75\\%$"},{"key":"C","text":"$80\\%$"},{"key":"D","text":"$90\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'The percentage correct is $\\frac{36}{45} \\times 100 = 80\\%$. The result $72\\%$ comes from an arithmetic error such as computing $\\frac{36}{50} \\times 100$. The result $75\\%$ comes from an incorrect setup such as dividing $\\frac{36}{48}$. The result $90\\%$ comes from misreading the problem, perhaps computing $\\frac{45 - 36}{45}$ and subtracting from $100\\%$ incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BOW4IS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive value of $x$ that satisfies $2x^2 = 32$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing both sides by $2$ gives $x^2 = 16$. Taking the positive square root yields $x = 4$. The value $2$ results from an arithmetic error such as computing $\\sqrt{32} \\div 4$ incorrectly. The value $8$ comes from dividing $32$ by $4$ instead of by $2$, or from halving $16$ instead of taking its square root. The value $16$ results from dividing $32$ by $2$ but stopping before taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BT2ZL1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A biologist surveys $625$ randomly selected trees in a national forest and finds that $\\hat{p} = 0.20$ of them show signs of disease. Using the formula $\\text{ME} = 1.96\\sqrt{\\frac{\\hat{p}(1 - \\hat{p})}{n}}$, what is the margin of error rounded to the nearest hundredth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.03', ARRAY['3/100', '0.03', '.03'], E'Substituting into the formula: $\\text{ME} = 1.96\\sqrt{\\frac{0.20 \\times 0.80}{625}}$. First compute the product in the numerator: $0.20 \\times 0.80 = 0.16$. Divide by $625$: $\\frac{0.16}{625} = 0.000256$. Take the square root: $\\sqrt{0.000256} = 0.016$. Multiply by $1.96$: $1.96 \\times 0.016 = 0.03136$. Rounded to the nearest hundredth, the margin of error is $0.03$. A common error is dividing $\\hat{p}$ by $n$ without multiplying by $(1 - \\hat{p})$ first, which gives an incorrect variance. Another error is forgetting the square root and computing $1.96 \\times 0.000256$, yielding a value that is far too small.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CHEBF8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A tank is being filled by two pipes. Pipe A fills the tank at a rate of $15$ liters per minute, and Pipe B fills the tank at a rate of $10$ liters per minute. If Pipe A runs alone for the first $4$ minutes and then both pipes run together, how many total minutes from the start does it take to fill a $210$-liter tank?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'In the first $4$ minutes, Pipe A fills $15 \\times 4 = 60$ liters. The remaining volume is $210 - 60 = 150$ liters. When both pipes run together, they fill at $15 + 10 = 25$ liters per minute. The time needed for the remaining $150$ liters is $\\frac{150}{25} = 6$ minutes. The total time from the start is $4 + 6 = 10$ minutes. A common error is forgetting to add the initial $4$ minutes, giving $6$ instead of $10$. Another error is using only Pipe A''s rate for the entire fill, yielding $\\frac{210}{15} = 14$ minutes.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DB7DKY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $3(2x - 5) + 4 = 5x + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$3$"},{"key":"C","text":"$13$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $13$. Distribute to get $6x - 15 + 4 = 5x + 2$, which simplifies to $6x - 11 = 5x + 2$. Subtract $5x$ from both sides to get $x - 11 = 2$, then add $11$ to both sides to get $x = 13$. The value $-13$ results from a sign error when adding $11$ to both sides. The value $3$ comes from an arithmetic slip during simplification. The value $21$ results from incorrectly distributing $3(2x - 5)$ as $6x - 5$ instead of $6x - 15$, leading to $6x - 1 = 5x + 2$ and $x = 3$, then further miscomputing by adding $18$ instead.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EDYQN9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp rises at an angle of $20^\\circ$ from horizontal ground. If the ramp covers a horizontal distance of $15$ feet, which expression gives the length of the ramp, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{15}{\\cos(20^\\circ)}$"},{"key":"B","text":"$15\\cos(20^\\circ)$"},{"key":"C","text":"$15\\tan(20^\\circ)$"},{"key":"D","text":"$\\frac{15}{\\sin(20^\\circ)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The horizontal distance ($15$ feet) is the side adjacent to the $20^\\circ$ angle, and the ramp is the hypotenuse. Using $\\cos(20^\\circ) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{15}{L}$, solving gives $L = \\frac{15}{\\cos(20^\\circ)}$. The expression $15\\cos(20^\\circ)$ incorrectly multiplies rather than divides, which would give a value smaller than $15$. The expression $15\\tan(20^\\circ)$ computes the vertical rise instead of the ramp length. The expression $\\frac{15}{\\sin(20^\\circ)}$ uses sine instead of cosine, confusing the adjacent side with the opposite side.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ER6RQ5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations $y = x^2 - 4x + k$ and $y = 2x - 5$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$1$"},{"key":"C","text":"$4$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the equations equal gives $x^2 - 4x + k = 2x - 5$, which simplifies to $x^2 - 6x + (k + 5) = 0$. For exactly one real solution, the discriminant must equal zero: $(-6)^2 - 4(1)(k + 5) = 0$, so $36 - 4k - 20 = 0$, giving $16 = 4k$ and $k = 4$. The value $-4$ results from a sign error when solving $4k = 16$. The value $1$ comes from an error in rearranging the equation, such as forgetting to move the $-5$ to the left side. The value $9$ results from computing $k + 5 = 9$ but reporting $9$ instead of subtracting $5$ to get $k = 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FQDJJ2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangle $PQR$ is similar to triangle $LMN$, where $P$ corresponds to $L$ and $Q$ corresponds to $M$. The sides of triangle $PQR$ have lengths $PQ = 15$, $QR = 20$, and $PR = 25$. If the perimeter of triangle $LMN$ is $36$, what is the length of side $MN$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'The perimeter of triangle $PQR$ is $15 + 20 + 25 = 60$. Since the triangles are similar, all corresponding sides share the same ratio. The ratio of the perimeters equals the ratio of corresponding sides: $\\frac{36}{60} = \\frac{3}{5}$. Since $Q$ corresponds to $M$ and $R$ corresponds to $N$, side $MN$ corresponds to $QR$. Therefore $MN = \\frac{3}{5} \\times 20 = 12$. A common error is using an inverted scale factor of $\\frac{5}{3}$, giving $\\frac{5}{3} \\times 20 = \\frac{100}{3} \\approx 33.3$. Another error is matching $MN$ to the wrong side, such as computing $\\frac{3}{5} \\times 15 = 9$ or $\\frac{3}{5} \\times 25 = 15$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FU2T8V', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $ABC$, the right angle is at vertex $B$. If $\\sin(A) = \\frac{7}{25}$ and $AC = 50$, what is the length of side $AB$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48', ARRAY['48'], E'Since $\\sin(A) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{BC}{AC} = \\frac{7}{25}$ and $AC = 50$, we get $BC = \\frac{7}{25} \\times 50 = 14$. To find $AB$, use the Pythagorean theorem: $AB = \\sqrt{AC^2 - BC^2} = \\sqrt{50^2 - 14^2} = \\sqrt{2500 - 196} = \\sqrt{2304} = 48$. A common error is confusing sine with cosine, computing $BC = \\frac{7}{25} \\times 50 = 14$ correctly but then reporting $BC$ as the answer instead of computing $AB$. Another error is using $\\cos(A) = \\frac{7}{25}$ to find $AB = \\frac{7}{25} \\times 50 = 14$, confusing which ratio involves the adjacent side.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GOJEYG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + 3x - 18 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factoring the quadratic gives $(x + 6)(x - 3) = 0$, so $x = -6$ or $x = 3$. Since the problem requires $x > 0$, the answer is $3$. A common error is selecting $-6$, which satisfies the equation but violates the constraint $x > 0$. Another error is attempting to use the quadratic formula and making an arithmetic mistake with the discriminant $9 + 72 = 81$, whose square root is $9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H7W9WV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(-1, 8)$ and $(3, -4)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/3', ARRAY['5/3', '1.666', '1.667'], E'First, find the slope: $m = \\frac{-4 - 8}{3 - (-1)} = \\frac{-12}{4} = -3$. Using the point $(3, -4)$ in point-slope form: $y - (-4) = -3(x - 3)$, which gives $y + 4 = -3x + 9$, so $y = -3x + 5$. The $x$-intercept occurs when $y = 0$: $0 = -3x + 5$, so $3x = 5$ and $x = \\frac{5}{3}$. A common error is computing the slope with the coordinates in the wrong order, yielding $m = 3$ instead of $m = -3$. Another error is confusing the $x$-intercept with the $y$-intercept and reporting $5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HAAUI7', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x - 6y = 18$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$3$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-3$. Set $x = 0$ in $3x - 6y = 18$ to get $-6y = 18$, so $y = -3$. Alternatively, rewrite in slope-intercept form: $y = \\frac{1}{2}x - 3$, confirming the $y$-intercept is $-3$. The value $3$ results from a sign error, dropping the negative. The value $-2$ comes from an arithmetic slip such as dividing $18$ by $-6$ incorrectly or confusing the slope with the intercept. The value $6$ is the $x$-intercept, not the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HIDZPL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym membership costs $\\$25$ per month plus a one-time registration fee of $\\$50$. The function $C(m) = 25m + 50$ gives the total cost, in dollars, for $m$ months of membership. What does the number $50$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The cost per month of the membership"},{"key":"B","text":"The one-time registration fee"},{"key":"C","text":"The total cost after $2$ months"},{"key":"D","text":"The number of months of membership"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that $50$ represents the one-time registration fee. In the function $C(m) = 25m + 50$, the constant term $50$ is the initial cost when $m = 0$, which corresponds to the registration fee paid once. The cost per month is represented by the coefficient $25$, not by $50$. The total cost after $2$ months would be $C(2) = 25(2) + 50 = 100$, not $50$. The number of months is represented by the variable $m$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HN8TPT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher wants to estimate the proportion of households in a region that recycle. She plans to survey a random sample and construct a $95\\%$ confidence interval. If she increases her sample size from $400$ to $1{,}600$, what happens to the margin of error?', NULL, $lyceon_json$[{"key":"A","text":"It is divided by $4$."},{"key":"B","text":"It is divided by $2$."},{"key":"C","text":"It is divided by $16$."},{"key":"D","text":"It stays the same because the confidence level did not change."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is proportional to $\\frac{1}{\\sqrt{n}}$. When the sample size increases from $400$ to $1{,}600$, the factor is $\\frac{\\sqrt{400}}{\\sqrt{1{,}600}} = \\frac{20}{40} = \\frac{1}{2}$. So the margin of error is divided by $2$. The distractor stating division by $4$ confuses the ratio of sample sizes ($\\frac{1{,}600}{400} = 4$) with the ratio of margins of error, forgetting the square root relationship. The distractor stating division by $16$ squares the sample size ratio instead of taking the square root. The distractor claiming no change incorrectly assumes margin of error depends only on the confidence level and not on sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JA71PW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages of six children in a group are $4$, $6$, $7$, $9$, $11$, and $11$. What is the median age of the children?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $6$ data values in order ($4, 6, 7, 9, 11, 11$), the median is the average of the $3$rd and $4$th values: $\\frac{7 + 9}{2} = 8$. The result $7$ comes from taking only the $3$rd value without averaging with the $4$th. The result $9$ comes from taking only the $4$th value without averaging with the $3$rd. The result $11$ is the mode, not the median.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2D7IW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A scientist models the concentration $c$ (in milligrams per liter) of a medication in a patient''s bloodstream $t$ hours after administration using the equation $c = -2t^2 + 16t$. According to this model, for how many hours is the concentration at least $24$ milligrams per liter?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Setting $-2t^2 + 16t \\geq 24$ gives $-2t^2 + 16t - 24 \\geq 0$. Dividing both sides by $-2$ (and reversing the inequality) gives $t^2 - 8t + 12 \\leq 0$. Factoring yields $(t - 2)(t - 6) \\leq 0$, which is satisfied when $2 \\leq t \\leq 6$. The duration is $6 - 2 = 4$ hours. A common error is solving $c = 24$ and reporting one root ($t = 2$ or $t = 6$) instead of computing the length of the interval. Another error is forgetting to reverse the inequality when dividing by a negative number, which gives an incorrect solution set.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L5S7OZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, angle $A$ measures $(3x + 10)^\\circ$, angle $B$ measures $(5x - 6)^\\circ$, and angle $C$ measures $(2x + 16)^\\circ$. What is the measure of angle $B$, in degrees?', NULL, $lyceon_json$[{"key":"A","text":"$58$"},{"key":"B","text":"$74$"},{"key":"C","text":"$48$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the angles in a triangle is $180^\\circ$: $(3x + 10) + (5x - 6) + (2x + 16) = 180$. Combining like terms: $10x + 20 = 180$, so $10x = 160$ and $x = 16$. Substituting into angle $B$: $5(16) - 6 = 74$ degrees. The value $58$ comes from finding angle $A$ instead ($3(16) + 10 = 58$), misreading which angle was asked for. The value $48$ comes from finding angle $C$ instead ($2(16) + 16 = 48$). The value $16$ comes from reporting the value of $x$ rather than substituting it into the expression for angle $B$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCL25Q', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells hardcover books for $\\$18$ each and paperback books for $\\$7$ each. A customer buys $9$ books and spends a total of $\\$107$. How many hardcover books did the customer buy?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the number of hardcover books and $p$ the number of paperback books. The system is $h + p = 9$ and $18h + 7p = 107$. Substituting $p = 9 - h$ into the revenue equation gives $18h + 7(9 - h) = 107$, which simplifies to $18h + 63 - 7h = 107$, then $11h = 44$, so $h = 4$. The distractor $3$ results from an arithmetic error such as miscalculating $107 - 63 = 44$ or $44 \\div 11$. The distractor $5$ is the number of paperback books ($p = 9 - 4 = 5$), not the hardcover count. The distractor $7$ arises from incorrectly setting up the price equation, such as swapping the per-unit costs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MMI8HG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company randomly assigned $200$ patients with chronic headaches to two groups of $100$. One group received a new medication, and the other received a placebo. Neither the patients nor the doctors knew which treatment each patient received. After twelve weeks, the group receiving the medication reported statistically significantly fewer headaches per month. Which conclusion is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The medication caused the reduction in headache frequency compared to the placebo."},{"key":"B","text":"The medication is associated with fewer headaches, but causation cannot be established."},{"key":"C","text":"The placebo group may have experienced fewer headaches if they had known they were receiving the placebo."},{"key":"D","text":"The result is unreliable because $100$ patients per group is too small a sample."}]$lyceon_json$::jsonb, 'A', NULL, E'This is a double-blind randomized controlled experiment. Random assignment eliminates confounding by distributing patient characteristics evenly across groups, and the double-blind design prevents placebo effects and observer bias from influencing the results. A statistically significant difference in this design supports a causal conclusion. The distractor claiming causation cannot be established incorrectly applies the limitation of observational studies to a randomized experiment. The distractor about the placebo group''s knowledge is irrelevant because the double-blind design ensured neither group knew their assignment. The distractor about sample size is incorrect because statistical significance was already achieved, indicating the sample was large enough to detect the effect.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NIR55A', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $x - y = 4$ and $x^2 - y^2 = 28$, what is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Recognize that $x^2 - y^2$ factors as $(x - y)(x + y)$. Substituting the given value of $x - y$ gives $4(x + y) = 28$. Dividing both sides by $4$ yields $x + y = 7$. A common error is attempting to solve for $x$ and $y$ individually without using the difference-of-squares identity, which leads to unnecessary complexity. Another error is dividing $28$ by $2$ instead of $4$, yielding the incorrect value $14$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NJMS4H', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A phone plan costs $\\$35$ per month plus $\\$0.10$ per text message. After applying a $20\\%$ employer discount to the total monthly bill, a customer paid $\\$44$. How many text messages did the customer send that month?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '200', ARRAY['200'], E'Let $t$ be the number of text messages. The total bill before the discount is $35 + 0.10t$. After a $20\\%$ discount, the customer pays $0.80(35 + 0.10t) = 44$. Dividing both sides by $0.80$ gives $35 + 0.10t = 55$. Subtracting $35$ from both sides gives $0.10t = 20$, so $t = 200$. A common error is forgetting the discount and solving $35 + 0.10t = 44$, which gives $t = 90$. Another error is applying the $20\\%$ discount only to the per-message charge rather than the total bill, leading to $35 + 0.08t = 44$ and $t = 112.5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O6BVQO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'As $x$ increases without bound, which of the following best describes the end behavior of the function $f(x) = -x^3 + 4x^2 - x + 7$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x)$ increases without bound"},{"key":"B","text":"$f(x)$ decreases without bound"},{"key":"C","text":"$f(x)$ approaches $7$"},{"key":"D","text":"$f(x)$ approaches $0$"}]$lyceon_json$::jsonb, 'B', NULL, E'The leading term of $f(x) = -x^3 + 4x^2 - x + 7$ is $-x^3$. For a polynomial, end behavior is determined by the leading term. Since the degree is odd and the leading coefficient is negative, as $x$ increases without bound, $-x^3$ decreases without bound, so $f(x)$ decreases without bound. The claim that $f(x)$ increases without bound ignores the negative leading coefficient and treats the function as if it had a positive cubic term. The claim that $f(x)$ approaches $7$ confuses the constant term with a horizontal asymptote, which polynomials of degree greater than zero do not have. The claim that $f(x)$ approaches $0$ confuses the behavior with that of certain rational functions whose numerator has lower degree than the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OH2EPV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $14$ meters and a width of $9$ meters. What is the area of the rectangle, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$46$"},{"key":"C","text":"$126$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is $A = l \\times w = 14 \\times 9 = 126$ square meters. The value $23$ comes from adding the length and width ($14 + 9 = 23$) instead of multiplying them. The value $46$ is the perimeter ($2(14 + 9) = 46$), resulting from confusing area with perimeter. The value $63$ results from an arithmetic slip such as computing $14 \\times 9$ as $7 \\times 9 = 63$, effectively halving one dimension.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGLI5L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has $10$ values with a mean of $42$. When an $11$th value is added, the mean becomes $44$. What is the $11$th value?', NULL, $lyceon_json$[{"key":"A","text":"$46$"},{"key":"B","text":"$62$"},{"key":"C","text":"$64$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'C', NULL, E'The original sum of the $10$ values is $10 \\times 42 = 420$. After adding the $11$th value, the new sum must be $11 \\times 44 = 484$. Therefore the $11$th value is $484 - 420 = 64$. The result $46$ confuses the new mean with the added value, simply adding $2$ to $44$. The result $62$ arises from an arithmetic error such as computing $482 - 420$. The result $84$ comes from incorrectly doubling the difference between the means and adding it to the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PXJIX7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $GHJ$, the measure of angle $G$ is $52^\\circ$ and the measure of angle $J$ is $61^\\circ$. What is the measure, in degrees, of angle $H$?', NULL, $lyceon_json$[{"key":"A","text":"$57$"},{"key":"B","text":"$67$"},{"key":"C","text":"$77$"},{"key":"D","text":"$113$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $H = 180 - 52 - 61 = 67$ degrees. The value $57$ results from an arithmetic slip in the subtraction, such as computing $180 - 52 - 61$ as $128 - 71$. The value $77$ comes from another arithmetic error, such as misreading $52$ as $42$. The value $113$ comes from adding $52 + 61 = 113$ and reporting the sum rather than subtracting it from $180$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
