INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXKRR5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $10$ red marbles, $6$ blue marbles, and $4$ green marbles. If one marble is drawn at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{6}$"},{"key":"B","text":"$\\frac{3}{10}$"},{"key":"C","text":"$\\frac{6}{16}$"},{"key":"D","text":"$\\frac{1}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $10 + 6 + 4 = 20$. There are $6$ blue marbles, so the probability of drawing a blue marble is $\\frac{6}{20} = \\frac{3}{10}$. The distractor $\\frac{1}{6}$ incorrectly uses the count of blue marbles as the denominator rather than the total count. The distractor $\\frac{6}{16}$ excludes the green marbles from the total, using $10 + 6 = 16$ as the denominator. The distractor $\\frac{1}{2}$ has no valid basis and likely results from misreading which group is being asked about.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R16O5X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'The system of equations $ax + 4y = 20$ and $6x + 8y = b$, where $a$ and $b$ are constants, has infinitely many solutions. What is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'A system of two linear equations has infinitely many solutions when the two equations are scalar multiples of each other. Comparing coefficients, the ratio of the $y$-coefficients is $\\frac{4}{8} = \\frac{1}{2}$. For the equations to be proportional, all coefficient ratios must be equal: $\\frac{a}{6} = \\frac{4}{8} = \\frac{20}{b} = \\frac{1}{2}$. From $\\frac{20}{b} = \\frac{1}{2}$, cross-multiplying gives $b = 40$. This means the first equation multiplied by $2$ yields the second equation: $2(ax + 4y) = 2(20)$ gives $2ax + 8y = 40$, and since $a = 3$, the second equation is $6x + 8y = 40$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R1E7AH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $f(x) = ax + 320$ models the number of pages remaining to be read in a book after $x$ days. After $6$ days, $200$ pages remain. After how many total days will the student have read exactly $280$ pages?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'First, find $a$ using the condition $f(6) = 200$: $6a + 320 = 200$, so $6a = -120$ and $a = -20$. The function is $f(x) = -20x + 320$. The book has $f(0) = 320$ pages total. The number of pages read after $x$ days is $320 - f(x) = 320 - (-20x + 320) = 20x$. Set $20x = 280$ to get $x = 14$. A common error is solving $f(x) = 280$ instead, which confuses pages remaining with pages read and gives $x = -2$. Another error is finding $a$ incorrectly by dividing $200$ by $6$, which ignores the initial $320$ pages.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R4M9H1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe requires $\\frac{3}{4}$ cup of sugar for every $2$ cups of flour. If a baker uses $7$ cups of flour, how many cups of sugar does the baker need?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{8}$"},{"key":"B","text":"$\\frac{21}{8}$"},{"key":"C","text":"$\\frac{7}{3}$"},{"key":"D","text":"$\\frac{14}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of sugar to flour is $\\frac{3/4}{2} = \\frac{3}{8}$ cup of sugar per cup of flour. For $7$ cups of flour the baker needs $\\frac{3}{8} \\times 7 = \\frac{21}{8}$ cups of sugar. The result $\\frac{7}{8}$ comes from using $\\frac{1}{8}$ as the unit rate, as if dividing $\\frac{1}{4}$ by $2$ instead of $\\frac{3}{4}$ by $2$. The result $\\frac{7}{3}$ comes from setting up the proportion incorrectly. The result $\\frac{14}{3}$ comes from inverting the ratio and computing $7 \\times \\frac{2}{3/4}$ incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R8BNH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'An investment increases in value by $20\\%$ during the first year and then decreases in value by $15\\%$ during the second year. If the investment is worth $\\$5{,}100$ at the end of the second year, what was the original value of the investment, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5000', ARRAY['5000'], E'Let $p$ be the original value. After a $20\\%$ increase, the value is $1.20p$. After a $15\\%$ decrease, the value is $1.20p \\times 0.85 = 1.02p$. Setting $1.02p = 5{,}100$ gives $p = \\frac{5{,}100}{1.02} = 5{,}000$. A common error is treating the net change as $20\\% - 15\\% = 5\\%$, which gives $\\frac{5{,}100}{1.05} \\approx 4{,}857$. Another error is reversing the operations by subtracting $20\\%$ and adding $15\\%$ in the wrong order when working backward.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJ6ZF4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer prints $96$ pages in $12$ minutes. At this constant rate, how many pages does the printer print in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$108$"},{"key":"B","text":"$128$"},{"key":"C","text":"$144$"},{"key":"D","text":"$160$"}]$lyceon_json$::jsonb, 'D', NULL, E'The printer prints $\\frac{96}{12} = 8$ pages per minute. In $20$ minutes it prints $8 \\times 20 = 160$ pages. The result $108$ comes from adding $12$ to $96$ instead of computing the rate. The result $128$ arises from an arithmetic error in multiplying the rate by $20$. The result $144$ comes from incorrectly multiplying $96$ by $\\frac{3}{2}$ as if $20$ were $1.5$ times $12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T57RRH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 6x + 10y + 18 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$16$"},{"key":"C","text":"$\\sqrt{18}$"},{"key":"D","text":"$\\sqrt{34}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square for both variables. Group terms: $(x^2 - 6x) + (y^2 + 10y) = -18$. Complete the square: $(x^2 - 6x + 9) + (y^2 + 10y + 25) = -18 + 9 + 25$, giving $(x - 3)^2 + (y + 5)^2 = 16$. Since $r^2 = 16$, the radius is $r = 4$. The value $16$ comes from reporting $r^2$ instead of taking the square root to find $r$. The value $\\sqrt{18}$ comes from using the constant term $18$ directly without completing the square. The value $\\sqrt{34}$ results from adding $9 + 25 = 34$ but forgetting to also add $18$ to the right side, computing $r^2 = 34$ incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U3D3TS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A central angle of a circle with radius $10$ subtends an arc of length $15$. What is the area of the sector formed by this central angle? (Give your answer in terms of a decimal.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '75', ARRAY['75'], E'The arc length formula is $s = r\\theta$, where $\\theta$ is in radians. Substituting: $15 = 10\\theta$, so $\\theta = \\frac{3}{2}$ radians. The area of a sector is $A = \\frac{1}{2}r^2\\theta = \\frac{1}{2}(10)^2\\left(\\frac{3}{2}\\right) = \\frac{1}{2}(100)\\left(\\frac{3}{2}\\right) = 75$. A common error is forgetting the $\\frac{1}{2}$ factor in the sector area formula, computing $r^2\\theta = 100 \\times \\frac{3}{2} = 150$. Another error is using the arc length directly as the angle, computing $\\frac{1}{2}(100)(15) = 750$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V5510A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A laptop originally priced at $\\$1{,}200$ is discounted by $15\\%$. A customer uses an additional coupon for $10\\%$ off the discounted price. What is the final price the customer pays?', NULL, $lyceon_json$[{"key":"A","text":"$\\$900$"},{"key":"B","text":"$\\$912$"},{"key":"C","text":"$\\$918$"},{"key":"D","text":"$\\$1{,}020$"}]$lyceon_json$::jsonb, 'C', NULL, E'After the $15\\%$ discount, the price is $1{,}200 \\times 0.85 = \\$1{,}020$. After the additional $10\\%$ coupon on the discounted price, the final price is $1{,}020 \\times 0.90 = \\$918$. The result $\\$900$ comes from combining the discounts as $25\\%$ off the original ($1{,}200 \\times 0.75$), which incorrectly treats successive discounts as additive. The result $\\$912$ arises from an arithmetic slip in computing $1{,}020 \\times 0.90$. The result $\\$1{,}020$ applies only the first discount and stops before applying the coupon.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VIEZJX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $5(2x - 3) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$14x - 15$"},{"key":"B","text":"$14x + 15$"},{"key":"C","text":"$10x - 15$"},{"key":"D","text":"$14x - 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $10x - 15 + 4x$. Combining like terms yields $14x - 15$. The expression $14x + 15$ results from incorrectly treating the $-3$ as $+3$ when distributing, a sign error. The expression $10x - 15$ comes from forgetting to add the $4x$ term entirely. The expression $14x - 3$ results from failing to distribute the $5$ to the $-3$, leaving the constant unchanged.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W9Z77Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cylindrical water tank has a diameter of $10$ feet and a height of $12$ feet. Water fills the tank to a depth of $9$ feet. What is the volume of the water in the tank, in cubic feet? (Express your answer as a multiple of $\\pi$, entering only the coefficient.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '225', ARRAY['225'], E'The radius of the cylinder is $\\frac{10}{2} = 5$ feet. The volume of water is $V = \\pi r^2 h = \\pi(5)^2(9) = \\pi(25)(9) = 225\\pi$ cubic feet. The coefficient of $\\pi$ is $225$. A common error is using the diameter instead of the radius: $\\pi(10)^2(9) = 900\\pi$, giving $900$. Another error is using the full height of the tank instead of the water depth: $\\pi(5)^2(12) = 300\\pi$, giving $300$. A third error is forgetting to halve the diameter, computing $\\pi(10)^2(9) = 900\\pi$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WGM6E5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $5x + 15 = 40$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $5$. Subtract $15$ from both sides of $5x + 15 = 40$ to get $5x = 25$, then divide both sides by $5$ to get $x = 5$. The value $-5$ results from a sign error when dividing $25$ by $5$. The value $8$ comes from dividing $40$ by $5$ without first subtracting $15$. The value $11$ results from an arithmetic slip such as computing $40 - 15 = 25$ but then dividing by a wrong number.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XRGBIN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^2 - 25}{3x + 5}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 5$"},{"key":"B","text":"$3x - 5$"},{"key":"C","text":"$3x^2 - 5$"},{"key":"D","text":"$9x - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^2 - 25$ is a difference of squares: $(3x)^2 - 5^2 = (3x - 5)(3x + 5)$. Dividing by $(3x + 5)$ cancels the common factor, leaving $3x - 5$. The expression $3x + 5$ results from neglecting the sign difference in the factored form, as if both factors were $(3x + 5)$. The expression $3x^2 - 5$ comes from incorrectly dividing each term of the numerator by $3$ and $5$ separately rather than factoring. The expression $9x - 5$ results from dividing only the constant term by $5$ while leaving the $9x$ coefficient unreduced.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y92GMJ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A phone plan charges a base fee of $\\$30$ per month plus $\\$0.10$ per text message sent. A customer''s monthly budget for the plan is at most $\\$45$. What is the maximum number of text messages the customer can send in a month?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '150', ARRAY['150'], E'The total monthly cost is $30 + 0.10m$, where $m$ is the number of text messages. The budget constraint gives $30 + 0.10m \\leq 45$. Subtracting $30$ from both sides yields $0.10m \\leq 15$. Dividing both sides by $0.10$ gives $m \\leq 150$. Since the number of messages must be a whole number, the maximum is $150$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YARQ5K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A polling organization surveyed a random sample of $1{,}200$ voters and found that $52\\%$ support a proposed ballot measure. The margin of error is $\\pm 2.8$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $52\\%$ of all voters support the ballot measure."},{"key":"B","text":"It is plausible that between $49.2\\%$ and $54.8\\%$ of all voters support the ballot measure."},{"key":"C","text":"If the poll were conducted again, the result would be between $49.2\\%$ and $54.8\\%$."},{"key":"D","text":"Between $49.2\\%$ and $54.8\\%$ of the $1{,}200$ sampled voters support the ballot measure."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $\\pm 2.8$ percentage points creates a confidence interval of $52\\% \\pm 2.8\\%$, or from $49.2\\%$ to $54.8\\%$. This interval estimates the plausible range for the true population proportion. The distractor stating exactly $52\\%$ ignores sampling variability and treats the sample statistic as the exact population parameter. The distractor about repeated polls confuses a confidence interval for the population parameter with a prediction about future sample results; different samples would yield different point estimates. The distractor applying the interval to the sampled voters is incorrect because the sample proportion is already known to be $52\\%$; the interval estimates the unknown population proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YTZ4G3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ has the equation $5x - 2y = 10$. Line $n$ is perpendicular to line $m$ and passes through the point $(5, 1)$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$\\frac{15}{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $3$. First, rewrite line $m$ in slope-intercept form: $5x - 2y = 10$ becomes $y = \\frac{5}{2}x - 5$, so the slope of line $m$ is $\\frac{5}{2}$. A line perpendicular to line $m$ has slope $-\\frac{2}{5}$. Using point-slope form with $(5, 1)$: $y - 1 = -\\frac{2}{5}(x - 5)$, which gives $y - 1 = -\\frac{2}{5}x + 2$, so $y = -\\frac{2}{5}x + 3$. The $y$-intercept is $3$. The value $-1$ results from a sign error when computing the negative reciprocal or when simplifying. The value $1$ comes from stopping at the $y$-coordinate of the given point without computing the intercept. The value $\\frac{15}{2}$ comes from using the slope $\\frac{5}{2}$ for line $n$ instead of the negative reciprocal, confusing parallel with perpendicular.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZHEF5B', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'What is the $y$-intercept of the function $f(x) = x^2 - 6x + 8$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$2$"},{"key":"C","text":"$6$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'The $y$-intercept is the value of $f(0)$. Substituting $x = 0$ gives $f(0) = 0 - 0 + 8 = 8$. The value $-8$ results from incorrectly negating the constant term. The value $2$ comes from confusing the $y$-intercept with an $x$-intercept, since $f(x) = (x - 2)(x - 4)$ has a root at $x = 2$. The value $6$ comes from reading the coefficient of $x$ rather than evaluating the function at $x = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20D7EYY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While drafting a research summary for a geography journal, a student wants to present evidence that permafrost thaw creates a self-reinforcing cycle while acknowledging that the rate of this process remains uncertain. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20GVU44', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the California Gold Rush of the 1840s and 1850s, thousands of prospectors abandoned their farms and trades to seek fortunes in the Sierra Nevada foothills. Most found little or no gold and returned home in debt. _______ the merchants who sold pickaxes, shovels, and provisions to the miners often accumulated far greater wealth than the prospectors themselves.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"As a result,"},{"key":"D","text":"That is,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "By contrast," because the third sentence presents information that directly contrasts with the preceding sentence: while most prospectors failed financially, the merchants who supplied them prospered. "In addition" merely adds a parallel point but fails to signal the opposition between the miners'' losses and the merchants'' gains. "As a result" implies that the merchants'' wealth was a direct consequence of the prospectors returning home in debt, but the passage presents the merchants'' success as a contrasting outcome, not a causal chain. "That is" signals a restatement or clarification, yet the third sentence introduces a new group (merchants) rather than restating information about the prospectors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20RUSJO', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Elephants in the wild have been observed pausing at the skeletal remains of deceased members of their herd, touching the bones gently with their trunks and sometimes standing silently for several minutes before moving on. They do not display this behavior when encountering the bones of other large animals such as rhinoceroses or buffalo. Because elephants appear to recognize and respond selectively to the remains of their own species, researchers have suggested that ________', $lyceon_json$[{"key":"A","text":"elephants possess a species-specific recognition of death that may reflect a form of social memory."},{"key":"B","text":"elephants have a stronger sense of smell than any other land mammal."},{"key":"C","text":"rhinoceroses and buffalo are incapable of recognizing skeletal remains."},{"key":"D","text":"elephant bones are chemically distinct from the bones of all other mammals."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes elephants selectively responding to the remains of their own species, which logically supports the conclusion that they possess a species-specific recognition of death reflecting social memory. The claim about elephants having a stronger sense of smell introduces a comparative sensory claim the passage never addresses. The claim about rhinoceroses and buffalo being incapable of recognizing remains shifts the focus to other species'' cognition, which the passage does not discuss. The claim about chemical distinctiveness of elephant bones introduces a biochemical hypothesis unrelated to the behavioral observation described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW215AVGB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'An urban planner argues that converting underused roadways into green spaces yields measurable public health benefits. Which finding, if true, would most directly support this argument?', E'Cities worldwide are experimenting with reclaiming automobile infrastructure for pedestrian and ecological use. Seoul, South Korea, demolished an elevated highway in 2005 and replaced it with Cheonggyecheon, a restored stream corridor lined with walking paths and native vegetation. In New York City, the High Line transformed an abandoned freight rail line into an elevated park. Advocates of such projects point to potential benefits ranging from reduced air pollution to increased physical activity among nearby residents. Critics counter that these conversions can raise surrounding property values, displacing lower-income residents through gentrification. A 2019 longitudinal study of neighborhoods adjacent to Cheonggyecheon measured air quality, hospital admission rates, and resident survey data over a twelve-year period following the highway''s removal.', $lyceon_json$[{"key":"A","text":"Neighborhoods within 500 meters of Cheonggyecheon showed a 22 percent decline in respiratory hospital admissions and a 15 percent increase in residents' self-reported weekly exercise hours over the twelve-year study period."},{"key":"B","text":"Property values within one kilometer of the High Line increased by an average of 35 percent within five years of the park's opening."},{"key":"C","text":"The demolition of Seoul's elevated highway cost approximately 380 billion South Korean won, funded primarily through municipal bonds."},{"key":"D","text":"Several European cities have considered similar highway-removal projects but have not yet begun construction."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding about a 22 percent decline in respiratory hospital admissions and a 15 percent increase in self-reported exercise directly quantifies public health benefits resulting from a highway-to-green-space conversion, supporting the urban planner''s argument. The finding about property value increases near the High Line addresses economic impact and potential gentrification, not public health outcomes. The construction cost figure describes the financial investment required but says nothing about health benefits to residents. The finding that European cities have considered similar projects but not begun construction provides no evidence of health outcomes from completed conversions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21HETYP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While preparing an article for a technology newsletter, a student wants to emphasize that the development of synthetic insulin was a collaborative achievement that built on earlier scientific work. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21QCID7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The giant Pacific octopus can change both the color and texture of its skin in less than a second. Specialized cells called chromatophores contain pigment sacs that expand or contract to produce different hues. <u>Beneath the chromatophores, reflecting cells called iridophores create iridescent blues and greens that the pigment cells alone cannot produce.</u> Working together, these cell layers allow the octopus to blend seamlessly into rocky seabeds, coral formations, and sandy ocean floors.', $lyceon_json$[{"key":"A","text":"It introduces an additional biological structure that extends the animal's color-changing capabilities beyond what the previously described cells provide."},{"key":"B","text":"It challenges the claim that octopuses can change their appearance rapidly."},{"key":"C","text":"It explains why scientists initially failed to understand octopus camouflage."},{"key":"D","text":"It describes the diet of the giant Pacific octopus in its natural habitat."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the sentence introduces an additional biological structure that extends the animal''s color-changing capabilities. The underlined sentence describes iridophores as a second cell type beneath the chromatophores that produces colors the pigment cells cannot, thereby adding to the explanation of the octopus''s camouflage system. The choice about challenging the claim of rapid appearance change is wrong because the sentence provides supplementary information about cell types rather than questioning the speed described in the opening sentence. The choice about scientists failing to understand camouflage is wrong because the passage does not mention any history of scientific misunderstanding. The choice about diet is wrong because the sentence discusses reflecting cells and color production, not feeding behavior.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2597JJJ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly one quarter of all known marine species. This extraordinary biodiversity arises from the reef''s complex three-dimensional structure, which provides shelter, breeding grounds, and hunting territory for thousands of organisms. Fish, crustaceans, mollusks, and sea turtles all depend on coral formations for survival. When reefs degrade due to warming waters or pollution, the cascading loss of habitat threatens entire marine food webs.', $lyceon_json$[{"key":"A","text":"Coral reefs support a disproportionately large share of marine biodiversity because of the complex habitat they provide, and their degradation endangers many species."},{"key":"B","text":"Coral reefs are the largest structures on the ocean floor and are expanding rapidly due to favorable ocean conditions."},{"key":"C","text":"Scientists have recently discovered that coral reefs are home to more plant species than any terrestrial ecosystem."},{"key":"D","text":"Marine pollution is the sole cause of coral reef degradation worldwide."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage emphasizes that coral reefs occupy a tiny fraction of ocean space yet support an outsized share of marine life due to their complex structure, and that reef degradation threatens this biodiversity. The choice describing reefs as supporting a disproportionately large share of marine biodiversity and noting the danger of degradation captures both key points. The claim that reefs are the largest structures and are expanding contradicts the passage, which describes reefs as occupying less than one percent of the ocean floor and facing degradation. The claim about plant species goes beyond anything stated; the passage discusses marine animals, not plant diversity. The claim that pollution is the sole cause of degradation misrepresents the passage, which also mentions warming waters as a contributing factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25SIFT4', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The documentary profiles three renowned ______ Wangari Maathai, who founded the Green Belt Movement in Kenya; Chico Mendes, who defended the Amazon rainforest in Brazil; and Dian Fossey, who studied mountain gorillas in Rwanda.', $lyceon_json$[{"key":"A","text":"conservationists:"},{"key":"B","text":"conservationists,"},{"key":"C","text":"conservationists;"},{"key":"D","text":"conservationists"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a colon after ''conservationists'' because the independent clause ''The documentary profiles three renowned conservationists'' introduces a list that specifies who those conservationists are. A colon is the conventional mark for introducing a list after a complete independent clause. A comma after ''conservationists'' is insufficient to introduce a formal list following an independent clause, and because the list items themselves contain internal commas (separated by semicolons), adding another comma at this boundary blurs the hierarchical punctuation structure. A semicolon after ''conservationists'' is inappropriate because a semicolon joins two independent clauses or separates items within a list; it does not introduce a list. Omitting punctuation entirely removes the necessary boundary between the introductory clause and the list, making the sentence difficult to parse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
