INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AVA5H7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists have long debated why some resource-rich countries experience slower economic growth than resource-poor countries—a phenomenon known as the "resource curse." One prominent explanation holds that resource wealth fuels corruption by concentrating revenue in the hands of political elites who face little pressure to develop diversified tax bases or invest in public goods. A competing hypothesis emphasizes the macroeconomic mechanism of "Dutch disease," in which commodity exports drive up a country''s currency value, making non-commodity sectors such as manufacturing and agriculture less competitive internationally. A third account focuses on institutional quality, arguing that countries with strong legal frameworks and transparent governance prior to resource discovery tend to manage windfall revenues effectively, while those with weak institutions see existing dysfunction amplified. The institutional account is particularly noteworthy because it implies that ________', $lyceon_json$[{"key":"A","text":"the economic impact of natural resource wealth is not determined by the resources themselves but by the governance structures already in place when the resources are exploited."},{"key":"B","text":"all resource-rich countries inevitably experience the resource curse regardless of their political and economic institutions."},{"key":"C","text":"Dutch disease can be prevented simply by limiting the volume of commodity exports a country produces."},{"key":"D","text":"corruption in resource-rich countries is exclusively caused by foreign corporations seeking to exploit weak regulatory environments."}]$lyceon_json$::jsonb, 'A', NULL, E'The institutional account argues that countries with strong prior governance manage resource wealth well while those with weak institutions see dysfunction amplified, implying that outcomes depend on pre-existing governance rather than the resources themselves. This is what the correct completion captures. The claim that all resource-rich countries inevitably experience the resource curse directly contradicts the institutional account, which holds that strong institutions can prevent negative outcomes. The claim about preventing Dutch disease by limiting export volume misrepresents the Dutch disease hypothesis, which concerns currency valuation effects rather than export volume caps. The claim attributing corruption exclusively to foreign corporations introduces an actor the passage never mentions and ignores the passage''s focus on domestic political elites and institutional structures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BJPGUU', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Throughout the twentieth century, linguists generally held that signed languages used by Deaf communities were simplified gestural systems lacking the grammatical complexity of spoken languages. This assumption was overturned in the 1960s when William Stokoe, a professor at Gallaudet University, published a systematic analysis of American Sign Language (ASL). Stokoe demonstrated that ASL possesses its own phonology, morphology, and syntax—organizational levels previously thought to exist only in spoken language. His work showed that signs are not holistic gestures but are composed of discrete, combinable units analogous to the phonemes of speech. Stokoe''s findings faced initial resistance from both hearing linguists and some members of the Deaf community, but subsequent research across dozens of sign languages worldwide has confirmed that all natural sign languages exhibit full linguistic complexity.', $lyceon_json$[{"key":"A","text":"Stokoe's analysis revealed that ASL and other sign languages possess full grammatical complexity, overturning the earlier assumption that they were simplified gestural systems."},{"key":"B","text":"Stokoe invented American Sign Language at Gallaudet University during the 1960s as an alternative to spoken English."},{"key":"C","text":"Hearing linguists have consistently supported the recognition of sign languages as fully complex linguistic systems since the early twentieth century."},{"key":"D","text":"Sign languages are easier for children to learn than spoken languages because signs are holistic gestures rather than combinations of smaller units."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how the prevailing view of sign languages as simplified systems was overturned by Stokoe''s demonstration that ASL possesses full phonological, morphological, and syntactic complexity. The choice about Stokoe''s analysis revealing full grammatical complexity and overturning earlier assumptions accurately captures this central narrative. The claim that Stokoe invented ASL misreads the passage, which states he analyzed an already existing language. The claim that hearing linguists have consistently supported sign language recognition directly contradicts the passage, which says the earlier consensus dismissed sign languages and that Stokoe faced initial resistance. The claim that sign languages are easier because signs are holistic gestures contradicts Stokoe''s key finding that signs are composed of discrete combinable units, not holistic gestures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DNZZVH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Determined to document the effects of deforestation on local bird populations, ______ spanned over two hundred square kilometers of tropical rainforest in southeastern Peru.', $lyceon_json$[{"key":"A","text":"the research area selected by the ecologists"},{"key":"B","text":"the ecologists selected a research area that"},{"key":"C","text":"a research area was selected by the ecologists that"},{"key":"D","text":"it was the ecologists who selected a research area that"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice places ''the ecologists'' as the subject of the main clause immediately after the introductory participial phrase ''Determined to document the effects of deforestation on local bird populations.'' A participial phrase must modify the subject of the clause it is attached to, and only the ecologists can logically be ''determined to document'' anything. Making ''the research area'' the subject creates a dangling modifier, because a research area cannot be ''determined to document'' effects. The passive construction ''a research area was selected by the ecologists'' also dangles the modifier by placing ''a research area'' as the grammatical subject. The cleft construction ''it was the ecologists who'' similarly dangles the modifier because the grammatical subject is the expletive ''it,'' not the ecologists themselves.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GY6AGA', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A marine biologist claims that octopuses display problem-solving abilities that rival those of many vertebrates. Which finding from the text, if true, would most directly support this claim?', E'Octopuses belong to the class Cephalopoda and possess the largest brains of any invertebrate relative to body size. In laboratory settings, researchers have observed octopuses navigating complex mazes, unscrewing jars to obtain food rewards, and using coconut shell halves as portable shelters—a behavior classified as tool use. One study documented an octopus that learned to turn off an overhead light by squirting water at the bulb, a behavior the animal repeated consistently over multiple trials. Field observations have also recorded octopuses stacking rocks to barricade the entrances to their dens, apparently to deter predators while the animals sleep.', $lyceon_json$[{"key":"A","text":"An octopus consistently learned to extinguish an overhead light by squirting water at the bulb, repeating the behavior across multiple trials."},{"key":"B","text":"Octopuses have the largest brains of any invertebrate relative to body size."},{"key":"C","text":"Cephalopods are classified as invertebrates and lack a backbone."},{"key":"D","text":"Octopuses are found in oceans worldwide, from tropical coral reefs to deep-sea trenches."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding about an octopus learning to extinguish a light by squirting water at the bulb and repeating the behavior across trials directly demonstrates problem-solving ability, supporting the claim that octopuses rival vertebrates in this capacity. The finding about brain size provides anatomical context that could be consistent with problem-solving ability but does not itself demonstrate the ability in action. The classification of cephalopods as invertebrates is a taxonomic fact irrelevant to the claim about problem-solving. The global distribution of octopuses describes geographic range, which has no bearing on cognitive ability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HDAHBL', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A literary scholar argues that Zora Neale Hurston''s use of free indirect discourse in her fiction was a deliberate narrative strategy to center Black vernacular speech as a vehicle for philosophical complexity, not merely as regional color. Which quotation from the text would most directly support this argument?', E'Zora Neale Hurston''s 1937 novel Their Eyes Were Watching God employs a dual narrative voice: a third-person narrator who speaks in Standard English and an interior voice that renders protagonist Janie Crawford''s thoughts in Black Southern vernacular. Critics of the Harlem Renaissance era sometimes dismissed Hurston''s use of dialect as a concession to white audiences'' appetite for folksy caricature. However, close analysis of the novel''s key passages reveals a more sophisticated design. In moments of Janie''s deepest self-reflection—her meditations on love, autonomy, and mortality—the narrative shifts entirely into vernacular free indirect discourse, dissolving the boundary between narrator and character. Hurston herself wrote in a 1934 essay that dialect is ''the force of feeling translated into words,'' arguing that vernacular expression carries philosophical weight that formal English often flattens. Scholars have also noted that Hurston reserved Standard English narration primarily for expository and transitional passages, using it as scaffolding rather than as the novel''s intellectual center.', $lyceon_json$[{"key":"A","text":"\"Critics of the Harlem Renaissance era sometimes dismissed Hurston's use of dialect as a concession to white audiences' appetite for folksy caricature.\""},{"key":"B","text":"\"In moments of Janie's deepest self-reflection—her meditations on love, autonomy, and mortality—the narrative shifts entirely into vernacular free indirect discourse, dissolving the boundary between narrator and character.\""},{"key":"C","text":"\"Hurston's 1937 novel Their Eyes Were Watching God employs a dual narrative voice: a third-person narrator who speaks in Standard English and an interior voice that renders protagonist Janie Crawford's thoughts in Black Southern vernacular.\""},{"key":"D","text":"\"Scholars have also noted that Hurston reserved Standard English narration primarily for expository and transitional passages, using it as scaffolding rather than as the novel's intellectual center.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The quotation about the narrative shifting entirely into vernacular free indirect discourse during Janie''s deepest meditations on love, autonomy, and mortality directly demonstrates that Hurston deployed vernacular as the vehicle for philosophical complexity, not mere regional color. The dismissal by Harlem Renaissance critics describes the opposing view the scholar is arguing against, not evidence supporting the scholar''s claim. The description of the dual narrative voice establishes the novel''s structural technique but does not show that vernacular specifically carries philosophical weight. The observation that Standard English serves as scaffolding supports the argument indirectly by describing what Standard English does, but it does not demonstrate what vernacular accomplishes in the novel''s most intellectually demanding moments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HLG7XI', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Historian Rashida Patel argues that the standard periodization of the Industrial Revolution — typically dated from roughly 1760 to 1840 in Britain — obscures the contributions of regions outside Europe. Patel documents extensive mechanized textile production in Mughal India during the seventeenth century and sophisticated water-powered milling operations in Song Dynasty China centuries earlier. She acknowledges that these earlier systems did not produce the sustained economic transformation associated with British industrialization but maintains that framing industrialization as a uniquely European phenomenon distorts the global history of technological innovation. Rather than proposing a single alternative chronology, Patel calls for a comparative framework that evaluates technological development across civilizations without privileging one region''s timeline as the universal standard.', $lyceon_json$[{"key":"A","text":"To argue that Mughal India and Song Dynasty China achieved higher levels of industrial output than eighteenth-century Britain."},{"key":"B","text":"To present a historian's case for reconceptualizing a major historical category so that it accounts for technological developments beyond a single region."},{"key":"C","text":"To provide a chronological overview of all major technological innovations from ancient times through the modern era."},{"key":"D","text":"To explain why most historians have rejected the traditional dating of the Industrial Revolution in recent scholarship."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating the text presents a historian''s case for reconceptualizing a major historical category to account for developments beyond a single region. Patel argues that standard periodization obscures non-European contributions and calls for a comparative framework — her purpose is to expand how industrialization is conceptualized across civilizations. The choice claiming India and China achieved higher output than Britain is wrong because Patel explicitly acknowledges that earlier systems did not produce the sustained transformation associated with British industrialization; she argues for broader recognition, not for superior output. The choice about a chronological overview of all innovations is wrong because Patel selectively cites two examples to support an argument about periodization, not to survey the full history of technology. The choice about most historians rejecting traditional dating is wrong because the passage presents Patel''s argument as a challenge to the standard view, not as a description of an already-accomplished shift in mainstream scholarship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IP9GKY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2020 study of urban noise pollution, acoustician Priya Chatterjee found that prolonged exposure to traffic noise not only caused hearing damage but also elevated cortisol levels in residents living near highways. Chatterjee argued that noise pollution should be treated as a public health crisis rather than a mere ______, since its physiological effects are measurable and cumulative.', $lyceon_json$[{"key":"A","text":"nuisance"},{"key":"B","text":"epidemic"},{"key":"C","text":"priority"},{"key":"D","text":"remedy"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "nuisance." The passage contrasts a serious classification (public health crisis) with a lesser one that Chatterjee believes is inadequate. A nuisance is something that causes annoyance or inconvenience but is not considered dangerous, which fits the downplayed category Chatterjee is arguing against. "Epidemic" means a widespread outbreak of disease, which would be a more severe classification than a public health crisis, not a lesser one — the sentence requires a term that trivializes the problem. "Priority" means something regarded as more important than other matters, but the passage requires a word that minimizes the seriousness of noise pollution, not one that elevates it. "Remedy" means a treatment or cure for a problem, which is an entirely different category from a classification of severity and produces an incoherent sentence in context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IWZO5C', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying coral reefs in the Pacific have documented a sharp decline in reef fish populations over the past decade. Overfishing and rising ocean temperatures have combined to ______ the delicate balance of the reef ecosystem, leaving many species without adequate food or shelter.', $lyceon_json$[{"key":"A","text":"disrupt"},{"key":"B","text":"reinforce"},{"key":"C","text":"document"},{"key":"D","text":"observe"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "disrupt." The passage describes overfishing and rising temperatures causing a decline in fish populations and leaving species without food or shelter, indicating the ecosystem''s balance has been thrown into disorder — the meaning of disrupt. "Reinforce" means to strengthen or support, which is the opposite of what the passage describes happening to the ecosystem. "Document" means to record or create a written account of something, but the passage states that the forces are actively damaging the ecosystem, not recording it. "Observe" means to watch or notice, but the passage describes destructive forces acting on the ecosystem, not passively watching it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J8YWKL', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the project manager nor the two lead engineers ______ able to determine why the prototype failed during the stress test. The team scheduled additional diagnostics for the following morning.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses ''were'' because in a ''neither...nor'' construction, the verb agrees with the subject nearest to it. The nearest subject is ''the two lead engineers,'' which is plural, so the plural past-tense verb ''were'' is required. The singular ''was'' incorrectly agrees with the more distant subject ''project manager'' rather than the nearer plural subject. The singular present perfect ''has been'' fails both in number agreement with the plural nearer subject and in tense, since the passage uses the past tense (''failed,'' ''scheduled''). The singular present-tense ''is'' disagrees in number with the nearer subject and conflicts with the past-tense context of the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KQQ655', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a brief article for a nature magazine, a student wants to explain why coral reefs are considered vital to marine ecosystems. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KZXTED', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'In the early 2000s, neuroscientists Marcus Raichle and colleagues identified a network of brain regions that are most active when a person is not engaged in any external task—a phenomenon they termed the default mode network (DMN). The DMN activates during mind-wandering, daydreaming, and self-referential thought, and it deactivates when a person focuses on a demanding cognitive task. Some researchers initially interpreted DMN activity as mere neural idling, but subsequent studies revealed that the network plays a constructive role: it enables autobiographical memory retrieval, future planning, and the simulation of others'' mental states. However, abnormally elevated DMN activity has been associated with rumination in depression and with attentional lapses, suggesting that the network''s contributions depend on context and regulation. The DMN thus challenges the assumption that productive brain function requires sustained external focus, while simultaneously demonstrating that unchecked internal processing can be maladaptive.', $lyceon_json$[{"key":"A","text":"The default mode network performs constructive cognitive functions during unfocused states, but its benefits depend on appropriate regulation, complicating the view that productive thinking requires sustained external attention."},{"key":"B","text":"The default mode network is exclusively responsible for causing depression and attentional deficits in clinical populations."},{"key":"C","text":"Raichle's research proved that mind-wandering is always more cognitively productive than focused attention on external tasks."},{"key":"D","text":"The default mode network was well understood by neuroscientists before Raichle's research and has not generated significant debate."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents the DMN as a network that performs constructive functions such as memory retrieval, future planning, and social cognition during unfocused states, while noting that unregulated DMN activity can lead to rumination and attentional lapses. The choice capturing constructive functions, context-dependent benefits, and the challenge to assumptions about focused attention integrates all three layers of the passage''s argument. The claim that the DMN exclusively causes depression and attentional deficits overstates one aspect; the passage describes an association with rumination and lapses, not exclusive causation, and highlights the network''s constructive roles as well. The claim that mind-wandering is always more productive than focused attention inverts the passage''s nuance, which presents the DMN''s value as context-dependent, not universally superior. The claim that the DMN was well understood before Raichle contradicts the passage, which presents Raichle''s identification of the network as a discovery and notes initial misinterpretation as neural idling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L74IFQ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a point of agreement and a point of disagreement between the authors of Text 1 and Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MAML34', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Many species of deep-sea fish produce their own light through a chemical process known as bioluminescence. _______ the anglerfish uses a glowing lure that dangles from its forehead to attract unsuspecting prey in the total darkness of the ocean depths.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Instead,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "For instance," because the second sentence provides a specific example — the anglerfish and its glowing lure — of the general claim made in the first sentence about deep-sea fish producing bioluminescence. "Nevertheless" incorrectly signals a concession or unexpected contrast, but the anglerfish example directly supports the opening statement rather than contradicting it. "Instead" implies the second sentence presents an alternative to or replacement for something, which does not match the relationship between the sentences. "Meanwhile" suggests two events happening simultaneously, but the passage is describing a general phenomenon and then illustrating it, not narrating concurrent events.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N8WX9S', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Astronomers initially expected that galaxies at the edges of the observable universe — those formed within the first few hundred million years after the Big Bang — would appear small, dim, and structurally simple. Data from the James Webb Space Telescope has revealed, however, that several of these early galaxies are surprisingly massive and well-organized, with defined spiral arms and mature stellar populations. _______ some astrophysicists have begun questioning whether current models of galaxy formation adequately account for the speed at which large-scale cosmic structures can develop.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Granted,"},{"key":"C","text":"For example,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Accordingly," because the third sentence describes a response that follows logically from the unexpected findings in the second sentence: because the telescope data contradicted expectations, scientists are now questioning their models. "Accordingly" captures this cause-and-effect progression. "Granted" introduces a concession — an acknowledgment of a point before countering it — but the third sentence extends and responds to the second sentence rather than conceding anything. "For example" treats the scientists'' questioning of models as an illustration of the telescope data, but the third sentence describes a consequence of the findings, not an instance of them. "Likewise" signals a parallel situation, yet the third sentence introduces a new development (questioning models) rather than describing something analogous to the telescope observations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NNX94I', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In 1928, Scottish bacteriologist Alexander Fleming noticed that a mold colony on a contaminated petri dish had created a bacteria-free zone around itself. He identified the mold as Penicillium notatum and hypothesized that it was producing a substance toxic to bacteria. Although Fleming published his findings, he lacked the resources to purify the substance in quantities sufficient for clinical use, and his paper attracted little immediate attention. It was not until 1940 that Howard Florey and Ernst Boris Chain at Oxford University developed methods to mass-produce the compound, which they named penicillin. Their work coincided with the urgent medical demands of World War II, when battlefield infections killed more soldiers than combat wounds. The timing of Florey and Chain''s breakthrough thus suggests that ________', $lyceon_json$[{"key":"A","text":"the wartime need for effective infection treatment provided both the funding and the institutional urgency necessary to translate Fleming's laboratory observation into a widely available medicine."},{"key":"B","text":"Fleming deliberately delayed publishing his discovery until wartime conditions would guarantee its commercial success."},{"key":"C","text":"penicillin would have been mass-produced in the 1920s if Fleming had access to better laboratory equipment."},{"key":"D","text":"Florey and Chain's contribution to penicillin's development was primarily administrative rather than scientific."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Fleming''s discovery languished for over a decade until Florey and Chain developed mass-production methods during a wartime period when infections were devastating military forces. The logical conclusion is that wartime urgency provided the conditions necessary to transform a laboratory observation into a widely available medicine. The claim that Fleming deliberately delayed publication contradicts the passage, which states he did publish his findings but lacked resources for purification. The claim about 1920s mass production introduces a counterfactual the passage does not support; the passage attributes the delay to insufficient resources, not equipment quality alone. The claim that Florey and Chain''s contribution was administrative misreads the passage, which credits them with developing scientific methods for mass production.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NZUQB1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, linguists assumed that all human languages share a universal set of core grammatical features, a view rooted in Noam Chomsky''s theory of universal grammar. However, fieldwork by linguist Daniel Everett among the Piraha people of the Amazon revealed a language that appeared to lack recursion — the embedding of one clause inside another — which Chomsky had identified as the defining property of human language. Everett''s findings ignited fierce debate: some linguists questioned his methodology, while others argued that the data demanded a fundamental revision of linguistic theory.', $lyceon_json$[{"key":"A","text":"It presents a widely held theoretical position, introduces findings that challenge it, and describes the resulting scholarly controversy."},{"key":"B","text":"It traces the career of a single researcher from early training through major discovery."},{"key":"C","text":"It compares two unrelated languages to demonstrate universal grammatical features."},{"key":"D","text":"It proposes a new theory of language acquisition and defends it with experimental data."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the text presents a widely held theoretical position, introduces challenging findings, and describes the resulting controversy. The passage first establishes Chomsky''s universal grammar as the dominant view, then introduces Everett''s contradictory findings about Piraha, and finally describes the debate those findings provoked. The choice about tracing a single researcher''s career is wrong because the passage focuses on an intellectual debate rather than on Everett''s biographical trajectory, and it never discusses his training. The choice about comparing two unrelated languages is wrong because the passage discusses only one language, Piraha, in relation to a theoretical claim, not a direct comparison between two languages. The choice about proposing and defending a new theory is wrong because the passage does not advocate for a replacement theory; it describes an existing challenge to universal grammar without resolving the debate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R6OWAX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The violinist performed three encores at the end of the ______ the audience, which had been clapping politely throughout the evening, erupted into a sustained standing ovation that lasted nearly five minutes.', $lyceon_json$[{"key":"A","text":"concert, and"},{"key":"B","text":"concert and"},{"key":"C","text":"concert, so"},{"key":"D","text":"concert so"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a comma followed by the coordinating conjunction ''and'' to join two independent clauses. When a coordinating conjunction connects two independent clauses, a comma must precede it. The conjunction ''and'' correctly signals that the second event follows from or accompanies the first without implying causation. Omitting the comma before ''and'' violates the convention requiring a comma before a coordinating conjunction joining two independent clauses, especially when the second clause is long and contains internal commas. Using a comma with ''so'' incorrectly implies that the audience''s ovation was a purpose or direct causal result of the encores, but the passage describes two parallel events rather than a cause-and-effect relationship. Using ''so'' without a comma compounds both errors: it omits the required comma before a coordinating conjunction joining independent clauses and mischaracterizes the logical relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SAVWFM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Renewable energy advocates often point to Denmark as a model for wind power ______ the country generates more than forty percent of its electricity from wind turbines, a figure unmatched by any other nation of comparable size.', $lyceon_json$[{"key":"A","text":"adoption;"},{"key":"B","text":"adoption,"},{"key":"C","text":"adoption"},{"key":"D","text":"adoption and"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a semicolon after ''adoption'' to join two independent clauses. The first clause, ''Renewable energy advocates often point to Denmark as a model for wind power adoption,'' and the second clause, ''the country generates more than forty percent of its electricity from wind turbines,'' are both complete sentences, and a semicolon is the appropriate mark for connecting closely related independent clauses without a coordinating conjunction. A comma after ''adoption'' creates a comma splice, joining two independent clauses with only a comma and no conjunction. Omitting punctuation entirely produces a run-on sentence by fusing two independent clauses with no boundary mark. Adding ''and'' without a preceding comma violates the convention requiring a comma before a coordinating conjunction joining two independent clauses and also changes the rhetorical relationship between the clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SXQ77U', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Founded in 1891 by railroad magnate Leland ______ Stanford University has grown into one of the most prestigious research institutions in the world.', $lyceon_json$[{"key":"A","text":"Stanford,"},{"key":"B","text":"Stanford;"},{"key":"C","text":"Stanford"},{"key":"D","text":"Stanford."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice places a comma after ''Stanford'' to close the introductory participial phrase ''Founded in 1891 by railroad magnate Leland Stanford'' before the main clause beginning with ''Stanford University has grown.'' A comma is the standard mark for setting off an introductory participial phrase from the independent clause that follows. A semicolon incorrectly signals a boundary between two independent clauses, but the introductory phrase is not an independent clause. Omitting punctuation entirely fuses the introductory phrase into the main clause, creating confusion between the proper noun ''Leland Stanford'' and ''Stanford University.'' A period creates a sentence fragment, since the participial phrase cannot stand alone as a complete sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U6J41Y', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological evidence suggests that the ancient Nabataeans, who inhabited the arid deserts of modern-day Jordan, constructed an elaborate system of channels, cisterns, and dams to capture and store seasonal rainfall. This hydraulic network sustained a population of tens of thousands in their capital, Petra, for several centuries. _______ recent geological surveys indicate that the region''s annual rainfall during the Nabataean period was not significantly higher than it is today, implying that the civilization''s survival depended less on favorable climate conditions than on sophisticated water-management engineering.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Notably,"},{"key":"D","text":"In contrast,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Notably," because the third sentence introduces a particularly significant finding — that rainfall levels were similar to today''s — which deepens the reader''s understanding of the Nabataeans'' achievement described in the first two sentences. "Notably" signals that the information that follows is especially important or surprising, which fits the revelation that the Nabataeans thrived not because of more rain but because of engineering skill. "Moreover" simply adds additional information in a parallel fashion, but the third sentence does more than add a fact: it reframes the significance of the water system by ruling out a climate-based explanation. "Consequently" implies the geological surveys were a direct result of the hydraulic network sustaining the population, which reverses the logical relationship in the passage. "In contrast" signals opposition between two ideas, but the third sentence reinforces and deepens the point about Nabataean engineering rather than contradicting anything stated earlier.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UJPD9A', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does the position presented in Text 2 relate to the position presented in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y1CCUZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The committee responsible for reviewing grant applications ______ to announce the finalists by the end of next week. Each application was evaluated on the basis of originality, feasibility, and potential community impact.', $lyceon_json$[{"key":"A","text":"expect"},{"key":"B","text":"expects"},{"key":"C","text":"are expecting"},{"key":"D","text":"have expected"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses the singular verb ''expects'' to agree with the singular subject ''committee.'' Although a committee is composed of multiple people, it functions as a single collective noun and takes a singular verb in Standard English. The plural verb ''expect'' treats ''committee'' as plural, which does not conform to the convention that collective nouns take singular verbs when referring to the group as a unit. The plural progressive ''are expecting'' also fails to agree with the singular ''committee.'' The plural perfect ''have expected'' similarly disagrees in number with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YIQD7A', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The novelist insisted that the publisher ______ the original cover design, arguing that the proposed replacement failed to capture the novel''s central themes. Despite pressure from the marketing department, the publisher eventually agreed.', $lyceon_json$[{"key":"A","text":"retain"},{"key":"B","text":"retains"},{"key":"C","text":"retained"},{"key":"D","text":"would retain"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses the subjunctive form ''retain'' because the verb ''insisted'' introduces a mandative subjunctive clause. In Standard English, verbs of demand, recommendation, or insistence require the base form of the verb in the subordinate ''that'' clause, regardless of the subject''s number or the tense of the main clause. The indicative ''retains'' incorrectly applies standard subject-verb agreement rules instead of using the subjunctive base form required after ''insisted that.'' The past tense ''retained'' incorrectly shifts the subordinate clause into the indicative past, but mandative subjunctive clauses do not take past-tense marking. The conditional ''would retain'' introduces a modal that is not used in the mandative subjunctive construction; ''would'' signals willingness or conditionality rather than the demand expressed by ''insisted.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZWP1QU', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Literary critic Amara Osei contends that the novels of Chimamanda Ngozi Adichie do not merely depict Nigerian society but actively ______ readers'' assumptions about African narratives. By embedding moments of mundane domesticity alongside scenes of political upheaval, Adichie refuses the expectation that African fiction must center on crisis, forcing readers to confront the reductive frameworks they bring to the text.', $lyceon_json$[{"key":"A","text":"validate"},{"key":"B","text":"catalog"},{"key":"C","text":"unsettle"},{"key":"D","text":"broadcast"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "unsettle." The passage describes Adichie as refusing expectations and forcing readers to confront their reductive frameworks, indicating she disturbs or destabilizes their assumptions — the meaning of unsettle. "Validate" means to confirm or endorse as correct, which is the opposite of what the passage describes, since Adichie challenges rather than affirms readers'' preexisting assumptions. "Catalog" means to systematically list or classify items, but the passage describes an active challenge to assumptions, not a neutral listing or organization of them. "Broadcast" means to transmit or widely disseminate information, but the passage describes Adichie disrupting assumptions, not spreading them to a wider audience.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
